mapper.select:
SELECT task_id, kind, unit_index, generation, dispatch_attempts FROM parse_unit
WHERE status = 'QUEUED' AND dispatched_at IS NULL AND next_dispatch_at <= #{now}
    AND next_run_at <= #{now}
ORDER BY next_dispatch_at, task_id, kind, unit_index LIMIT #{limit}

mapper.update:
UPDATE parse_unit SET status = 'RUNNING', attempts = attempts + 1,
    lease_token = #{token}, lease_until = #{until}, updated_at = #{now}
WHERE  AND status = 'QUEUED' AND next_run_at <= #{now}

UPDATE parse_unit SET status = #{status}, result_text = #{text,jdbcType=LONGVARCHAR},
    error_code = #{code,jdbcType=VARCHAR}, error_message = #{message,jdbcType=VARCHAR},
    lease_token = NULL, lease_until = NULL, updated_at = #{now}
WHERE  AND status = 'RUNNING' AND lease_token = #{token,jdbcType=VARCHAR}
